fn reverse(a: &Vec<i32>) -> Vec<i32> {
    let n = a.len();
    let mut reversed = Vec::with_capacity(n); // Create a new vector with the same capacity

    for i in (0..n).rev() { // Iterate from n-1 to 0
        reversed.push(a[i]); // Push elements in reverse order
    }

    reversed // Return the new reversed vector
}